//! 📼️ Individually authored AVI headers, formats and retained chunk relationships.
use crate::standards::v1_0::subsets::any::schema::snapshot::*;
use semio_framework_os_kernel::sqlite_snapshot::{ValueError, ValueRefusalKind};

fn invalid(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn work(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::WorkLimit,message)}
fn ownership(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::OwnershipLimit,message)}
fn allocation(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::AllocationFailed,message)}

use std::collections::BTreeMap;
use semio_framework_os_kernel::{sqlite_snapshot::{artifact::{Cell,RowWriter,NativeEncodingBound,reconstruct_text,reconstruct_blob},validate_sqlite_database_schema,SnapshotEncoding,SqliteDatabase,SqliteRow,SqliteSnapshotControl,SqliteSnapshotPhase},ArtifactSqliteSnapshot};

type Entities<'a>=BTreeMap<i64,&'a SqliteRow>;
type Groups<'a>=BTreeMap<i64,Vec<&'a SqliteRow>>;
fn checkpoint(control:&mut SqliteSnapshotControl<'_>,position:usize,total:usize)->Result<(),ValueError>{if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,total)?;}Ok(())}
fn entities<'a>(database:&'a SqliteDatabase,table:&str,columns:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Entities<'a>,ValueError>{let rows=&database.table(table)?.rows;let mut result=BTreeMap::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;if row.values.len()!=columns||row.rowid<=0||row.integer(0)?!=row.rowid||result.insert(row.rowid,row).is_some(){return Err(invalid(format!("{table} requires unique positive aliased identities and exact columns")));}}Ok(result)}
fn singleton<'a>(rows:&Entities<'a>)->Result<&'a SqliteRow,ValueError>{if rows.len()!=1{return Err(invalid("AVI requires singleton identity one"));}rows.get(&1).copied().ok_or_else(||invalid("AVI requires singleton identity one"))}
fn same_owner(rows:&Entities<'_>,parents:&Entities<'_>,required:bool,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{for(position,id)in rows.keys().enumerate(){checkpoint(control,position,rows.len())?;if !parents.contains_key(id){return Err(invalid("AVI one-to-one entity has an unknown owner"));}}if required&&rows.len()!=parents.len(){return Err(invalid("AVI required stream header is missing"));}Ok(())}
fn groups<'a>(rows:&Entities<'a>,parents:&Entities<'_>,control:&mut SqliteSnapshotControl<'_>)->Result<Groups<'a>,ValueError>{let mut result:Groups<'a>=BTreeMap::new();for(position,&row)in rows.values().enumerate(){checkpoint(control,position,rows.len())?;let parent=row.integer(1)?;if !parents.contains_key(&parent){return Err(invalid("AVI ordered entity has an unknown owner"));}result.entry(parent).or_default().push(row);}for rows in result.values_mut(){checkpoint(control,0,rows.len())?;let mut slots=vec![None;rows.len()];for(position,&row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let ordinal=usize::try_from(row.integer(2)?).map_err(|error|invalid(error.to_string()))?;if slots.get_mut(ordinal).ok_or_else(||invalid("AVI ordinals must be dense"))?.replace(row).is_some(){return Err(invalid("AVI ordinals must be unique"));}}rows.clear();for(position,row)in slots.into_iter().enumerate(){checkpoint(control,position,0)?;rows.push(row.ok_or_else(||invalid("AVI ordinals must be dense"))?);}}Ok(result)}
fn ordinal(value:usize)->Result<Cell<'static>,ValueError>{Ok(Cell::Integer(i64::try_from(value).map_err(|error|work(error.to_string()))?))}
fn u32_value(row:&SqliteRow,column:usize)->Result<u32,ValueError>{u32::try_from(row.integer(column)?).map_err(|error|invalid(error.to_string()))}
fn u16_value(row:&SqliteRow,column:usize)->Result<u16,ValueError>{u16::try_from(row.integer(column)?).map_err(|error|invalid(error.to_string()))}
fn i32_value(row:&SqliteRow,column:usize)->Result<i32,ValueError>{i32::try_from(row.integer(column)?).map_err(|error|invalid(error.to_string()))}
fn boolean(row:&SqliteRow,column:usize)->Result<bool,ValueError>{match row.integer(column)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("AVI requires a boolean integer"))}}
fn write_riff(out:&mut RowWriter<'_,'_>,table:&str,parent:i64,chunks:&[RiffChunk])->Result<(),ValueError>{for(index,chunk)in chunks.iter().enumerate(){out.insert(table,&[Cell::Integer(parent),ordinal(index)?,Cell::Text(&chunk.fourcc),Cell::Blob(&chunk.data)])?;}Ok(())}
fn read_riff(rows:Option<&Vec<&SqliteRow>>,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<RiffChunk>,ValueError>{let mut result=Vec::new();for &row in rows.into_iter().flatten(){checkpoint(control,result.len(),0)?;result.push(RiffChunk{fourcc:reconstruct_text(control,row.text(3)?)?,data:reconstruct_blob(control,row.blob(4)?)?});}Ok(result)}


#[path="🧮️semantic/🦀️.rs"]
mod semantic;
fn visit_rows(snapshot:&AviSnapshot,out:&mut RowWriter<'_,'_>)->Result<(),ValueError>{
 let add=|count:usize,size:usize|count.checked_add(size).ok_or_else(||work("AVI semantic row count overflow"));let mut rows=2usize;
 for size in[snapshot.main_header.reserved.len(),snapshot.unknown_chunks.len(),snapshot.hdrl_extra.len(),snapshot.streams.len().checked_mul(3).ok_or_else(||work("AVI stream row count overflow"))?]{rows=add(rows,size)?;}out.check_rows(rows)?;
 for stream in &snapshot.streams{rows=add(add(rows,stream.chunks.len())?,stream.strl_extra.len())?;out.check_rows(rows)?;out.checkpoint_total(rows)?;}
out.insert("avi_document",&[Cell::Text(&snapshot.schema),Cell::Integer(i64::from(snapshot.idx1_present))])?;
  let m=&snapshot.main_header;out.insert_key("avi_main_header",1,&[Cell::Integer(i64::from(m.micro_sec_per_frame)),Cell::Integer(i64::from(m.max_bytes_per_sec)),Cell::Integer(i64::from(m.padding_granularity)),Cell::Integer(i64::from(m.flags)),Cell::Integer(i64::from(m.total_frames)),Cell::Integer(i64::from(m.initial_frames)),Cell::Integer(i64::from(m.streams)),Cell::Integer(i64::from(m.suggested_buffer_size)),Cell::Integer(i64::from(m.width)),Cell::Integer(i64::from(m.height))])?;
  for(index,value)in m.reserved.iter().enumerate(){out.insert("avi_main_reserved",&[Cell::Integer(1),ordinal(index)?,Cell::Integer(i64::from(*value))])?;}
  for(index,s)in snapshot.streams.iter().enumerate(){let kind=match &s.strf{AviStreamFormat::BitmapInfo{..}=>"bitmapInfo",AviStreamFormat::WaveFormat{..}=>"waveFormat",AviStreamFormat::Raw{..}=>"raw"};let id=out.insert("avi_stream",&[Cell::Integer(1),ordinal(index)?,Cell::Text(kind)])?;let h=&s.strh;
   out.insert_key("avi_stream_header",id,&[Cell::Text(&h.fcc_type),Cell::Text(&h.fcc_handler),Cell::Integer(i64::from(h.flags)),Cell::Integer(i64::from(h.priority)),Cell::Integer(i64::from(h.language)),Cell::Integer(i64::from(h.initial_frames)),Cell::Integer(i64::from(h.scale)),Cell::Integer(i64::from(h.rate)),Cell::Integer(i64::from(h.start)),Cell::Integer(i64::from(h.length)),Cell::Integer(i64::from(h.suggested_buffer_size)),Cell::Integer(i64::from(h.quality)),Cell::Integer(i64::from(h.sample_size)),Cell::Integer(i64::from(h.rc_frame_left)),Cell::Integer(i64::from(h.rc_frame_top)),Cell::Integer(i64::from(h.rc_frame_right)),Cell::Integer(i64::from(h.rc_frame_bottom)),Cell::Integer(i64::from(h.rc_frame_width)),Cell::Blob(&h.strh_extra)])?;
   match &s.strf{
    AviStreamFormat::BitmapInfo{size,width,height,planes,bit_count,compression,size_image,x_pels_per_meter,y_pels_per_meter,colors_used,colors_important}=>out.insert_key("avi_bitmap_info",id,&[Cell::Integer(i64::from(*size)),Cell::Integer(i64::from(*width)),Cell::Integer(i64::from(*height)),Cell::Integer(i64::from(*planes)),Cell::Integer(i64::from(*bit_count)),Cell::Text(compression),Cell::Integer(i64::from(*size_image)),Cell::Integer(i64::from(*x_pels_per_meter)),Cell::Integer(i64::from(*y_pels_per_meter)),Cell::Integer(i64::from(*colors_used)),Cell::Integer(i64::from(*colors_important))])?,
    AviStreamFormat::WaveFormat{format_tag,channels,samples_per_sec,avg_bytes_per_sec,block_align,bits_per_sample,extra}=>out.insert_key("avi_wave_format",id,&[Cell::Integer(i64::from(*format_tag)),Cell::Integer(i64::from(*channels)),Cell::Integer(i64::from(*samples_per_sec)),Cell::Integer(i64::from(*avg_bytes_per_sec)),Cell::Integer(i64::from(*block_align)),Cell::Integer(i64::from(*bits_per_sample)),Cell::Blob(extra)])?,
    AviStreamFormat::Raw{data}=>out.insert_key("avi_raw_format",id,&[Cell::Blob(data)])?
   }
   for(index,c)in s.chunks.iter().enumerate(){out.insert("avi_stream_chunk",&[Cell::Integer(id),ordinal(index)?,Cell::Text(&c.fourcc),Cell::Blob(&c.data),Cell::Integer(i64::from(c.keyframe))])?;}write_riff(out,"avi_stream_extra",id,&s.strl_extra)?;
  }write_riff(out,"avi_unknown_chunk",1,&snapshot.unknown_chunks)?;write_riff(out,"avi_hdrl_extra",1,&snapshot.hdrl_extra)?;Ok(())
}

impl ArtifactSqliteSnapshot for AviSnapshot{
 fn decode_sqlite_snapshot_native(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{let limits=control.limits();semantic::extent(limits)?;store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|record,native|{semantic::borrowed(record,limits,native)?;Self::__dsl_from_record_controlled(record,native)},control)}
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,ValueError>{
  semantic::typed(self,SqliteSnapshotPhase::EncodeNative,control)?;
  store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),control)
 }

 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{semantic::typed(self,SqliteSnapshotPhase::EncodeNative,control)?;let mut bound=NativeEncodingBound::file_only(control)?;bound.add(32768)?;bound.repeated(self.schema.len(),24)?;let scalar=std::mem::size_of::<semio_framework_dsl_record::FieldValue>()*2+64;bound.repeated(self.main_header.reserved.len(),scalar)?;for stream in &self.streams{bound.add(16384)?;bound.repeated(stream.strh.fcc_type.len(),24)?;bound.repeated(stream.strh.fcc_handler.len(),24)?;bound.repeated(stream.strh.strh_extra.len(),scalar)?;match &stream.strf{AviStreamFormat::BitmapInfo{compression,..}=>bound.repeated(compression.len(),24)?,AviStreamFormat::WaveFormat{extra,..}=>bound.repeated(extra.len(),scalar)?,AviStreamFormat::Raw{data}=>bound.repeated(data.len(),scalar)?,}for chunk in &stream.chunks{bound.add(2048)?;bound.repeated(chunk.fourcc.len(),24)?;bound.repeated(chunk.data.len(),scalar)?;}for chunk in &stream.strl_extra{bound.add(1024)?;bound.repeated(chunk.fourcc.len(),24)?;bound.repeated(chunk.data.len(),scalar)?;}}for chunk in self.unknown_chunks.iter().chain(&self.hdrl_extra){bound.add(1024)?;bound.repeated(chunk.fourcc.len(),24)?;bound.repeated(chunk.data.len(),scalar)?;}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{semantic::extent(control.limits())?;let mut out=RowWriter::new(Self::SQLITE_SCHEMA,control)?;visit_rows(self,&mut out)?;out.finish()}
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{
  validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;
  let documents=entities(database,"avi_document",3,control)?;let d=singleton(&documents)?;let main=entities(database,"avi_main_header",11,control)?;let m=singleton(&main)?;let reserved_rows=groups(&entities(database,"avi_main_reserved",4,control)?,&main,control)?;let stream_entities=entities(database,"avi_stream",4,control)?;let stream_rows=groups(&stream_entities,&documents,control)?;
  let headers=entities(database,"avi_stream_header",20,control)?;same_owner(&headers,&stream_entities,true,control)?;let bitmaps=entities(database,"avi_bitmap_info",12,control)?;same_owner(&bitmaps,&stream_entities,false,control)?;let waves=entities(database,"avi_wave_format",8,control)?;same_owner(&waves,&stream_entities,false,control)?;let raws=entities(database,"avi_raw_format",2,control)?;same_owner(&raws,&stream_entities,false,control)?;
  let chunks=groups(&entities(database,"avi_stream_chunk",6,control)?,&stream_entities,control)?;let extras=groups(&entities(database,"avi_stream_extra",5,control)?,&stream_entities,control)?;let unknown=groups(&entities(database,"avi_unknown_chunk",5,control)?,&documents,control)?;let hdrl=groups(&entities(database,"avi_hdrl_extra",5,control)?,&documents,control)?;
  let mut reserved=Vec::new();for &row in reserved_rows.get(&1).into_iter().flatten(){checkpoint(control,reserved.len(),0)?;reserved.push(u32_value(row,3)?);}
  let mut streams=Vec::new();for &s in stream_rows.get(&1).into_iter().flatten(){checkpoint(control,streams.len(),0)?;let h=headers.get(&s.rowid).ok_or_else(||invalid("AVI stream header is missing"))?;let strf=match s.text(3)?{
   "bitmapInfo"=>{let f=bitmaps.get(&s.rowid).ok_or_else(||invalid("AVI bitmap parameters are missing"))?;if waves.contains_key(&s.rowid)||raws.contains_key(&s.rowid){return Err(invalid("AVI bitmap choice has unexpected parameters"));}AviStreamFormat::BitmapInfo{size:u32_value(f,1)?,width:i32_value(f,2)?,height:i32_value(f,3)?,planes:u16_value(f,4)?,bit_count:u16_value(f,5)?,compression:reconstruct_text(control,f.text(6)?)?,size_image:u32_value(f,7)?,x_pels_per_meter:i32_value(f,8)?,y_pels_per_meter:i32_value(f,9)?,colors_used:u32_value(f,10)?,colors_important:u32_value(f,11)?}},
   "waveFormat"=>{let f=waves.get(&s.rowid).ok_or_else(||invalid("AVI wave parameters are missing"))?;if bitmaps.contains_key(&s.rowid)||raws.contains_key(&s.rowid){return Err(invalid("AVI wave choice has unexpected parameters"));}AviStreamFormat::WaveFormat{format_tag:u16_value(f,1)?,channels:u16_value(f,2)?,samples_per_sec:u32_value(f,3)?,avg_bytes_per_sec:u32_value(f,4)?,block_align:u16_value(f,5)?,bits_per_sample:u16_value(f,6)?,extra:reconstruct_blob(control,f.blob(7)?)?}},
   "raw"=>{let f=raws.get(&s.rowid).ok_or_else(||invalid("AVI raw parameters are missing"))?;if bitmaps.contains_key(&s.rowid)||waves.contains_key(&s.rowid){return Err(invalid("AVI raw choice has unexpected parameters"));}AviStreamFormat::Raw{data:reconstruct_blob(control,f.blob(1)?)?}},
   _=>return Err(invalid("AVI stream format is unknown"))};
   let mut owned_chunks=Vec::new();for &c in chunks.get(&s.rowid).into_iter().flatten(){checkpoint(control,owned_chunks.len(),0)?;owned_chunks.push(AviChunk{fourcc:reconstruct_text(control,c.text(3)?)?,data:reconstruct_blob(control,c.blob(4)?)?,keyframe:boolean(c,5)?});}
   streams.push(AviStream{strh:AviStreamHeader{fcc_type:reconstruct_text(control,h.text(1)?)?,fcc_handler:reconstruct_text(control,h.text(2)?)?,flags:u32_value(h,3)?,priority:u16_value(h,4)?,language:u16_value(h,5)?,initial_frames:u32_value(h,6)?,scale:u32_value(h,7)?,rate:u32_value(h,8)?,start:u32_value(h,9)?,length:u32_value(h,10)?,suggested_buffer_size:u32_value(h,11)?,quality:i32_value(h,12)?,sample_size:u32_value(h,13)?,rc_frame_left:i32_value(h,14)?,rc_frame_top:i32_value(h,15)?,rc_frame_right:i32_value(h,16)?,rc_frame_bottom:i32_value(h,17)?,rc_frame_width:u8::try_from(h.integer(18)?).map_err(|error|invalid(error.to_string()))?,strh_extra:reconstruct_blob(control,h.blob(19)?)?},strf,chunks:owned_chunks,strl_extra:read_riff(extras.get(&s.rowid),control)?});
  }
  let result=Self{schema:reconstruct_text(control,d.text(1)?)?,main_header:AviMainHeader{micro_sec_per_frame:u32_value(m,1)?,max_bytes_per_sec:u32_value(m,2)?,padding_granularity:u32_value(m,3)?,flags:u32_value(m,4)?,total_frames:u32_value(m,5)?,initial_frames:u32_value(m,6)?,streams:u32_value(m,7)?,suggested_buffer_size:u32_value(m,8)?,width:u32_value(m,9)?,height:u32_value(m,10)?,reserved},streams,idx1_present:boolean(d,2)?,unknown_chunks:read_riff(unknown.get(&1),control)?,hdrl_extra:read_riff(hdrl.get(&1),control)?};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,1,1)?;Ok(result)
 }
}

